mapper.select:
select t.invoice_order_id invoiceOrderId,t.user_id userId,t.phone,t.community_id communityId,
t.heading_id headingId,t.heading_type headingType,t.buyer_name buyerName,t.buyer_tax_no buyerTaxNo,
t.buyer_address buyerAddress,t.buyer_bank buyerBank,t.buyer_bank_no buyerBankNo,t.email,
t.invoice_type invoiceType,t.biz_category bizCategory,t.amount,t.invoice_id invoiceId,t.state,
t.invoice_no invoiceNo,t.invoice_code invoiceCode,t.pdf_url pdfUrl,t.fail_reason failReason,t.remark,
t.status_cd statusCd,t.create_time createTime,t.update_time updateTime
from invoice_order t
where 1 = 1

    and t.invoice_order_id= #{invoiceOrderId}


    and t.invoice_order_id in

        #{item}



    and t.user_id= #{userId}


    and t.phone= #{phone}


    and t.community_id= #{communityId}


    and t.heading_id= #{headingId}


    and t.heading_type= #{headingType}


    and t.buyer_name= #{buyerName}


    and t.invoice_type= #{invoiceType}


    and t.biz_category= #{bizCategory}


    and t.invoice_id= #{invoiceId}


    and t.state= #{state}


    and t.state in

        #{item}



    and t.invoice_no= #{invoiceNo}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update invoice_order t set t.status_cd = #{statusCd}

    , t.heading_id= #{headingId}


    , t.heading_type= #{headingType}


    , t.buyer_name= #{buyerName}


    , t.buyer_tax_no= #{buyerTaxNo}


    , t.buyer_address= #{buyerAddress}


    , t.buyer_bank= #{buyerBank}


    , t.buyer_bank_no= #{buyerBankNo}


    , t.email= #{email}


    , t.invoice_type= #{invoiceType}


    , t.biz_category= #{bizCategory}


    , t.amount= #{amount}


    , t.invoice_id= #{invoiceId}


    , t.state= #{state}


    , t.invoice_no= #{invoiceNo}


    , t.invoice_code= #{invoiceCode}


    , t.pdf_url= #{pdfUrl}


    , t.fail_reason= #{failReason}

where 1=1

    and t.invoice_order_id= #{invoiceOrderId}


    and t.remark= #{remark}

